module WhbThermo.Tests.SteamGoldenTests

open System
open System.Globalization
open System.IO
open Xunit
open Ganfoss.ROP
open WhbThermo.Domain
open WhbThermo.Steam

/// Grid campaign for IAPWS-IF97 against an independent implementation
/// (the `iapws` Python package), generated by tools/generate_golden.py.
///
/// This complements If97Tests, which checks the handful of verification values
/// printed in the standard. Those prove the equations are transcribed correctly;
/// this proves the region selection and the whole operating envelope behave.
module private Reference =

    let private read name =
        let file = Path.Combine(AppContext.BaseDirectory, "reference", name)
        if not (File.Exists file) then [||]
        else
            let lines = File.ReadAllLines file
            let header = lines.[0].Split(',')
            lines
            |> Array.skip 1
            |> Array.map (fun line ->
                Array.zip header (line.Split(',')) |> Map.ofArray)

    let number (row: Map<string, string>) key =
        Double.Parse(row.[key], CultureInfo.InvariantCulture)

    let states = read "iapws-states.csv"
    let saturation = read "iapws-saturation.csv"

open Reference

let private model =
    match If97.load () with
    | Success (m, _) -> m
    | Failure msgs -> failwith (msgs |> List.map string |> String.concat "; ")

[<Fact>]
let ``single phase grid matches an independent IF97 implementation`` () =
    Assert.True(states.Length > 0, "run tools/generate_golden.py first")

    let failures = ResizeArray<string>()
    for row in states do
        let t = number row "T_K"
        let pMPa = number row "P_MPa"
        match If97.properties model (t * 1.0<K>) (pMPa * 10.0<bar>) with
        | Failure msgs ->
            failures.Add ($"{t} K, {pMPa} MPa: " + (msgs |> List.map string |> String.concat "; "))
        | Success (s, _) ->
            let expectedRegion = if row.["region"] = "region1" then 1 else 2
            if s.Region <> expectedRegion then
                failures.Add $"{t} K, {pMPa} MPa: region {s.Region}, expected {expectedRegion}"

            let check name (ours: float) (theirs: float) =
                let deviation = abs (ours - theirs) / abs theirs
                if deviation > 1e-6 then
                    failures.Add $"{t} K, {pMPa} MPa: {name} {deviation:e2} apart"

            check "v" s.SpecificVolume (number row "v_m3_kg")
            check "h" s.Enthalpy (number row "h_kJ_kg")
            check "s" s.Entropy (number row "s_kJ_kgK")
            check "cp" s.Cp (number row "cp_kJ_kgK")

    Assert.True(failures.Count = 0, String.Join("\n", failures))

/// The saturation line across real WHB drum pressures, 5 to 160 bar.
[<Fact>]
let ``saturation line matches across the drum pressure range`` () =
    Assert.True(saturation.Length > 0, "run tools/generate_golden.py first")

    let failures = ResizeArray<string>()
    for row in saturation do
        let pBar = number row "P_bar"
        match If97.saturatedAt model (pBar * 1.0<bar>) with
        | Failure msgs ->
            failures.Add ($"{pBar} bar: " + (msgs |> List.map string |> String.concat "; "))
        | Success (s, _) ->
            let check name (ours: float) (theirs: float) (tolerance: float) =
                let deviation = abs (ours - theirs) / abs theirs
                if deviation > tolerance then
                    failures.Add ($"{pBar} bar: {name} {deviation:P3} apart "
                                  + $"(ours {ours:F4}, reference {theirs:F4})")

            check "Tsat" (float s.SaturationTemperature) (number row "Tsat_K") 1e-6
            check "rho_l" (float s.Liquid.Density) (number row "rho_l_kg_m3") 1e-6
            check "rho_v" (float s.Vapour.Density) (number row "rho_v_kg_m3") 1e-6
            check "h_l" s.Liquid.Enthalpy (number row "h_l_kJ_kg") 1e-6
            check "h_v" s.Vapour.Enthalpy (number row "h_v_kJ_kg") 1e-6
            check "hfg" s.LatentHeat (number row "hfg_kJ_kg") 1e-6

    Assert.True(failures.Count = 0, String.Join("\n", failures))

/// Physical monotonicity across the drum range: liquid density and latent heat
/// fall with pressure, vapour density rises. A sign error in region selection
/// would break one of these long before it broke a spot value.
[<Fact>]
let ``saturation properties are monotonic in pressure`` () =
    let pressures = [ 5.0; 10.0; 20.0; 40.0; 60.0; 80.0; 100.0; 120.0; 140.0; 160.0 ]
    let states =
        pressures
        |> List.map (fun p ->
            match If97.saturatedAt model (p * 1.0<bar>) with
            | Success (s, _) -> s
            | Failure msgs -> failwith (msgs |> List.map string |> String.concat "; "))

    for a, b in List.pairwise states do
        Assert.True(a.SaturationTemperature < b.SaturationTemperature, "Tsat must rise")
        Assert.True(a.Liquid.Density > b.Liquid.Density, "liquid density must fall")
        Assert.True(a.Vapour.Density < b.Vapour.Density, "vapour density must rise")
        Assert.True(a.LatentHeat > b.LatentHeat, "latent heat must fall")

/// Enthalpy of vaporisation must equal the enthalpy difference of the two
/// saturated states, at every pressure. Trivially true if the code is right and
/// immediately false if the wrong region is selected on either side.
[<Fact>]
let ``latent heat equals the saturated enthalpy difference`` () =
    for p in [ 5.0; 30.0; 70.0; 110.0; 150.0 ] do
        match If97.saturatedAt model (p * 1.0<bar>) with
        | Success (s, _) ->
            Assert.Equal(s.Vapour.Enthalpy - s.Liquid.Enthalpy, s.LatentHeat, 9)
        | Failure msgs -> failwith (msgs |> List.map string |> String.concat "; ")
